def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c, grid[r][c])
             for r in range(h) for c in range(w) if grid[r][c] != 0]

    forms = [
        lambda r, c: r,
        lambda r, c: c,
        lambda r, c: r + c,
        lambda r, c: r - c,
    ]

    candidates = []
    for form in forms:
        lines = {}
        valid = True
        for r, c, color in cells:
            offset = form(r, c)
            if offset in lines and lines[offset] != color:
                valid = False
                break
            lines[offset] = color
        if valid and lines:
            candidates.append((len(lines), lines))

    # The input consists of parallel colored lines; their count is the
    # period used to extend the pattern.
    _, lines = max(candidates, key=lambda item: item[0])
    period = len(lines)
    pattern = {offset % period: color for offset, color in lines.items()}

    # Select the same line coordinate used by the input pattern.
    chosen_form = None
    for form in forms:
        mapping = {}
        valid = True
        for r, c, color in cells:
            offset = form(r, c)
            if offset in mapping and mapping[offset] != color:
                valid = False
                break
            mapping[offset] = color
        if valid and mapping == lines:
            chosen_form = form
            break

    if chosen_form is None:
        chosen_form = forms[0]

    return [
        [pattern[chosen_form(r, c) % period] for c in range(w)]
        for r in range(h)
    ]
